// Cached manifest for native apps
let manifestCache = null;
let fileDownloadManager = null;

/**
 * Load manifest.json for native app file management
 * @returns {Promise<object>}
 */
async function loadManifest() {
  if (manifestCache) {
    return manifestCache;
  }

  try {
    const response = await fetch('/data/manifest.json');
    if (!response.ok) {
      throw new Error(`Failed to load manifest: ${response.statusText}`);
    }
    manifestCache = await response.json();
    console.log('📋 Loaded file manifest:', manifestCache);
    return manifestCache;
  } catch (error) {
    console.error('Failed to load manifest:', error);
    return null;
  }
}

/**
 * Get FileDownloadManager instance (lazy initialization)
 * @returns {FileDownloadManager}
 */
function getDownloadManager() {
  if (!fileDownloadManager) {
    fileDownloadManager = new FileDownloadManager();
  }
  return fileDownloadManager;
}

/**
 * Get data URL for a LIDAR file
 * - Native apps: Load from bundled files or download on-demand
 * - Web: Use cloud URLs
 * @param {string} filename - LAZ filename
 * @returns {Promise<string>} URL or file path
 */
export async function getDataUrl(filename) {
  // Web version: Use cloud URLs
  if (PlatformDetector.isWeb()) {
    if (BLOB_URLS[filename]) {
      return BLOB_URLS[filename];
    }
    // Development fallback
    return `/data/${filename}`;
  }

  // Native app: Check manifest for bundled/downloadable files
  const manifest = await loadManifest();
  if (!manifest) {
    console.warn('⚠️ Manifest not loaded, falling back to cloud URL');
    return BLOB_URLS[filename] || `/data/${filename}`;
  }

  // Check if file is bundled with the app
  const bundledFile = manifest.bundled.find(f => f.filename === filename);
  if (bundledFile) {
    console.log(`📦 Loading bundled file: ${filename}`);
    // Convert web path to native file URI
    const localPath = PlatformDetector.convertFileSrc(bundledFile.path);
    return localPath;
  }

  // Check if file is available for download
  const downloadableFile = manifest.downloadable.find(f => f.filename === filename);
  if (downloadableFile) {
    console.log(`⬇️ File requires download: ${filename}`);
    try {
      const downloadManager = getDownloadManager();
      const localPath = await downloadManager.getOrDownloadFile(
        downloadableFile,
        (progress, name) => {
          console.log(`Download progress: ${name} - ${progress}%`);
        }
      );
      return localPath;
    } catch (error) {
      console.error(`Failed to download ${filename}:`, error);
      // Fallback to cloud URL if download fails
      return downloadableFile.url;
    }
  }

  // File not in manifest - fall back to cloud URL
  console.warn(`⚠️ File not in manifest: ${filename}, using cloud URL`);
  return BLOB_URLS[filename] || `/data/${filename}`;
}
